from PIL import Image
def blob(i, cond, x0=200,x1=440,y0=350,y1=480):
    im=Image.open(f'captures/wrist_{i:03d}.png').convert('L'); px=im.load()
    xs=[];ys=[]
    for y in range(y0,y1):
        for x in range(x0,x1):
            if cond(px[x,y]): xs.append(x); ys.append(y)
    return len(xs), round(sum(xs)/len(xs),2), round(sum(ys)/len(ys),2), min(xs),max(xs),min(ys),max(ys)
print('pin bright', blob(10, lambda v: v>200))
print('pin dark', blob(10, lambda v: v<120))
for i in range(11,15): print(i, blob(i, lambda v: v<70))
EOF

