import workcell, math, re
tested={(0,0),(0,-.5),(0,.5),(0,-1),(0,1),(-.5,0),(-1,0),(-1.4,0),(.5,0),(1,0),(-.95,.3),(-.95,.6),(-.95,.9),(-.95,-.3),(-.95,-.6),(-.95,-.9)}
cands=[]
for dx in [-1.3,-0.6,-0.25,0.1,-0.95,0.45,0.8,1.15]:
    for dy in [0.15,0.5,0.85,1.2,-0.15,-0.5,-0.85,-1.2]:
        if math.hypot(dx,dy)<=1.45: cands.append((dx,dy))
cands.sort(key=lambda p:(abs(p[0]+0.95)>0.5, -p[1]))
for dx,dy in cands:
    st=workcell.call("robot","status").data; 
    if st["clock_s"]>13*60: print("time reserve reached"); break
    r=workcell.call("robot","insert",str(round(400.68+dx,2)),str(round(268.79+dy,2)))
    print(dx,dy,r.text[:60])
    if r.ok: print("SEATED"); break
print(workcell.call("robot","status").text)
EOF

